int main() {
    int n, m;
    cin >> n;
    vector<int> ans(n);
    for (int i = 0; i < n; i++) {
        cin >> ans[i];
    }
    cin >> m;
    // left 左边界 right右边界下一个选择的位置
    int left = 0, right = 0;
    int res = -100000000;
    int tmp = 0;

    while (right < n) {
        // 只考虑窗口为M的情况
        if (right - left + 1 < m) {
            tmp += ans[right];
            right++;
            continue;
        }
        // 窗口大小为M+1，left 右移
        if (right - left + 1 > m) {
            tmp -= ans[left];
            left++;
        }
        tmp += ans[right];
        res = max(res, tmp);
        right++;
    }
​
    cout << res;
    return 0;
}

