            // 窗口还不够大，继续加元素
            if (right - left + 1 < m) {
                tmp += ans[right];
                right++;
                continue;
            }
​
            // 窗口太大了，缩小窗口
            if (right - left + 1 > m) {
                tmp -= ans[left];
                left++;
            }
​
            tmp += ans[right];
            res = Math.max(res, tmp);
            right++;
        }
​
        System.out.println(res);
    }
}
