package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
func main() {
    reader := bufio.NewReader(os.Stdin)
​
    // 读取 n
    line, _ := reader.ReadString('\n')
    n, _ := strconv.Atoi(strings.TrimSpace(line))
​
    // 读取数组
    line, _ = reader.ReadString('\n')
    fields := strings.Fields(line)
    ans := make([]int, n)
    for i := 0; i < n; i++ {
        ans[i], _ = strconv.Atoi(fields[i])
    }
​
    // 读取 m
    line, _ = reader.ReadString('\n')
    m, _ := strconv.Atoi(strings.TrimSpace(line))
​
    left, right := 0, 0
    res := -100000000
    tmp := 0
​
    for right < n {
        if right-left+1 < m {
            tmp += ans[right]
            right++
            continue
        }
​
        if right-left+1 > m {
            tmp -= ans[left]
            left++
        }
​
        tmp += ans[right]
        if tmp > res {
            res = tmp
        }
        right++
    }
​
    fmt.Println(res)
}
